<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {uploadAttachment} from './attachmentUpload.js';
const pendingFiles=ref([]),attachmentStates=ref({}),reviewChecks=ref({}),invitedAgent=ref('');
const paired=ref(false),pairCode=ref(''),topics=ref([]),selected=ref(''),agentId=ref(''),messages=ref([]),jobs=ref([]),text=ref(''),busy=ref(false),notice=ref('正在连接…'),online=ref(false),history=ref(null);
const settingsOpen=ref(false),serverUrl=ref(''),accessKey=ref(''),server=ref(null),tested=ref(false);
let timer,lastSubmission=null,refreshing=false,historyKey='',cursor=0,historyRows=new Map(),generation=0;
const ownerKey=t=>JSON.stringify([t.ownerType||'agent',t.ownerId||t.agentName]);
const labels={waiting_approval:'等待原生工具审批',review_required:'执行中断 · 接力已暂停',blocked_config:'上下文或配置不可用 · 接力已暂停',recovering:'正在恢复已保存的结果',interrupted:'已中断 · 不自动重跑',preparing:'正在持久保存',queued:'已接受 · 等待执行',running:'服务端执行中',cancelling:'正在取消',cancelled:'已取消',publishing:'正在保存回复',completed:'回复已保存',failed:'执行失败'};
const agents=computed(()=>[...new Map(topics.value.map(t=>[ownerKey(t),{id:ownerKey(t),name:(t.ownerType==='group'?'群聊 · ':'')+t.agentName,avatar:t.avatar,model:t.model,executable:t.executable}])).values()]);
const visibleTopics=computed(()=>topics.value.filter(t=>ownerKey(t)===agentId.value));
const currentTopic=computed(()=>topics.value.find(t=>t.key===selected.value));
const keyAllowed=computed(()=>Boolean(isSecureContext&&server.value?.credentialExchangeAllowed));
const errors={GROUP_MODE_REQUIRES_DESKTOP:'此群聊模式请在桌面执行',GROUP_MEMBER_UNAVAILABLE:'此成员配置暂不可用',DEPENDENCY_REVIEW_REQUIRED:'同一话题有待核对的执行，请先处理暂停任务',DESKTOP_CONTEXT_REQUIRED:'此消息引用了仅在桌面可用的上下文',CONFIG_SNAPSHOT_CORRUPT:'执行配置校验失败，请在桌面重新发布',GROUP_CONTEXT_UNAVAILABLE:'有效上下文暂不可用',ATTACHMENT_BLOB_MISSING:'附件暂未同步，请等待电脑补齐',ATTACHMENT_BLOB_CORRUPT:'附件完整性校验失败，请重新同步',ATTACHMENT_TEXT_UNAVAILABLE:'此文件的文本尚不可用',ATTACHMENT_TYPE_REJECTED:'支持 PNG、JPEG、WebP、PDF 和 UTF-8 文本文件',ATTACHMENT_STORAGE_BUDGET:'附件空间已达到上限',ATTACHMENT_REQUEST_BUDGET:'附件请求过多，请稍后重试',MODEL_IMAGE_UNSUPPORTED:'当前模型不支持图片，请在电脑端选择支持图片的模型并发布配置',EXECUTION_CONFIG_REQUIRED:'请先在电脑端发布有效 Agent 配置',PAIR_REQUIRED:'输入你的 Key 连接会话',HTTPS_REQUIRED:'当前入口尚未启用 HTTPS，不能提交 Key',SERVER_NOT_APPROVED:'此地址尚未由服务端批准，请使用已获授权的服务器',PROTECTED_HOST_NOT_READY:'安全链路或服务端接入尚未就绪，暂不接收访问凭据',AUTH_FAILED:'访问凭据不正确',AUTH_RATE_LIMIT:'尝试过于频繁，请稍后重试',AGENT_NOT_EXECUTABLE:'此 Agent 尚未配置服务端执行能力',EXECUTION_INTERRUPTED_REVIEW_REQUIRED:'执行曾被中断，需确认工具副作用后另行发起，系统不会自动重跑'};
async function api(route,body){
 const r=await fetch('/mobile/api/'+route,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',redirect:'error',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});
 const result=await r.json();if(!r.ok){if(r.status===401&&result.error?.code==='PAIR_REQUIRED')paired.value=false;throw Object.assign(Error(errors[result.error?.code]||'请求未完成，请检查连接'),{code:result.error?.code});}return result;
}
function resetHistory(){invitedAgent.value='';reviewChecks.value={};pendingFiles.value=[];attachmentStates.value={};generation++;historyKey='';cursor=0;historyRows=new Map();messages.value=[];jobs.value=[];lastSubmission=null;}
async function session(){try{const r=await api('session');paired.value=true;online.value=true;server.value=r.server||server.value;serverUrl.value=r.server?.serverUrl||serverUrl.value;topics.value=r.topics;const existing=topics.value.find(t=>t.key===(r.selectedTopic||selected.value));if(existing){agentId.value=ownerKey(existing);selected.value=existing.key;}else{agentId.value=agents.value[0]?.id||'';selected.value=visibleTopics.value[0]?.key||'';resetHistory();}await refresh();}catch(e){notice.value=e.message;}}
async function pair(){busy.value=true;try{await api('pair',{code:pairCode.value});pairCode.value='';await session();settingsOpen.value=false;}catch(e){notice.value=e.message;}finally{busy.value=false;}}
async function connectionInfo(){try{server.value=await api('connection');serverUrl.value=server.value.serverUrl||server.value.suggestedServerUrl||'';online.value=true;if(keyAllowed.value){server.value=await api('connection/test',{serverUrl:serverUrl.value});tested.value=true;}}catch{notice.value='安全连接尚未就绪，尚未提交任何凭据';}}
async function testConnection(){busy.value=true;tested.value=false;accessKey.value='';try{server.value=await api('connection/test',{serverUrl:serverUrl.value});tested.value=true;notice.value='服务器身份和受保护接入已确认';}catch(e){notice.value=e.message;}finally{busy.value=false;}}
async function connect(){if(!keyAllowed.value||!tested.value)return;busy.value=true;const key=accessKey.value;accessKey.value='';try{await api('connection/authenticate',{serverUrl:serverUrl.value,apiKey:key});resetHistory();await session();settingsOpen.value=false;notice.value='已保存服务器连接，使用受限设备会话';}catch(e){notice.value=e.message;}finally{busy.value=false;}}
async function disconnect(){busy.value=true;accessKey.value='';try{await api('connection/disconnect',{});paired.value=false;topics.value=[];resetHistory();tested.value=false;settingsOpen.value=true;notice.value='此设备会话已撤销，可重新认证';}catch(e){notice.value=e.message;}finally{busy.value=false;}}
function selectAgent(){selected.value=visibleTopics.value[0]?.key||'';changeTopic();}
async function changeTopic(){resetHistory();try{await api('selection',{key:selected.value});await refresh();}catch(e){notice.value=e.message;}}
async function refresh(){
 if(!paired.value||!selected.value||refreshing)return;refreshing=true;const key=selected.value,epoch=generation;
 const stick=historyKey!==key||!history.value||history.value.scrollHeight-history.value.scrollTop-history.value.clientHeight<80;
 try{if(historyKey!==key){historyRows=new Map();cursor=0;historyKey=key;}let result;do{result=await api('conversations/'+encodeURIComponent(key)+'?after='+cursor);if(selected.value!==key||epoch!==generation)return;for(const row of result.messages){if(row.deleted)historyRows.delete(row.id);else historyRows.set(row.id,row.message);}cursor=result.next;}while(result.hasMore);
  messages.value=[...historyRows.values()].sort((a,b)=>a.timestamp-b.timestamp);jobs.value=result.executions;online.value=true;if(currentTopic.value){currentTopic.value.messageCount=messages.value.length;if(result.topicState)Object.assign(currentTopic.value,result.topicState);}
  if(currentTopic.value?.attachmentsEnabled){const ids=messages.value.filter(m=>m.attachments?.length).slice(-100).map(m=>m.id);if(ids.length){const status=await api('conversations/'+encodeURIComponent(key)+'/attachments/status',{messageIds:ids});if(selected.value!==key||epoch!==generation)return;attachmentStates.value=Object.fromEntries(status.attachments.map(a=>[a.messageId+'/'+a.attachmentId,a]));}}
  if(!busy.value)notice.value='中央会话已更新';await nextTick();if(stick&&history.value)history.value.scrollTop=history.value.scrollHeight;
 }catch(e){online.value=false;notice.value=e.message||'连接中断，重新连接后恢复状态';}finally{refreshing=false;}
}
async function submit(submission,kind='message'){
 busy.value=true;notice.value='正在提交…';const key=selected.value;lastSubmission={key,body:submission,kind};
 try{const accepted=await api('conversations/'+encodeURIComponent(key)+(kind==='invitation'?'/invitations':'/messages'),submission);notice.value='已持久接受 · '+(labels[accepted.state]||accepted.state);if(kind!=='invitation'){text.value='';pendingFiles.value=[];}await refresh();}catch(e){notice.value='尚未确认接受，可重试同一次提交：'+e.message;}finally{busy.value=false;}
}
function selectFiles(event){for(const file of event.target.files||[]){if(pendingFiles.value.length>=8)break;if(file.size>20*1024*1024){notice.value='单个附件需在 20 MB 以内';continue;}if(!pendingFiles.value.some(f=>f.file.name===file.name&&f.file.size===file.size&&f.file.lastModified===file.lastModified))pendingFiles.value.push({file,progress:0,error:'',uploadId:null});}event.target.value='';}
function attachmentUrl(message,attachment){return '/mobile/api/conversations/'+encodeURIComponent(selected.value)+'/attachments/messages/'+encodeURIComponent(message.id)+'/'+encodeURIComponent(attachment.id);}
async function send(){
 if((!text.value.trim()&&!pendingFiles.value.length)||busy.value||currentTopic.value?.executable===false)return;
 busy.value=true;const key=selected.value,epoch=generation;
 try{const ids=[];for(const item of pendingFiles.value){item.error='';try{item.uploadId=await uploadAttachment(api,key,item.file,n=>item.progress=n);ids.push(item.uploadId);}catch(e){item.error=e.message;throw e;}}if(key!==selected.value||epoch!==generation)return;await submit({requestId:crypto.randomUUID(),text:text.value,...(ids.length?{attachments:ids}:{})});}
 catch(e){notice.value=e.message+'；附件保留在当前页面，连接恢复后可重试。';}finally{busy.value=false;}
}
function retry(){
 const latest=[...jobs.value].reverse().find(j=>j.own&&j.state!=='cancelled');const original=latest&&messages.value.find(m=>m.id===latest.userMessageId);
 const submission=lastSubmission?.key===selected.value?lastSubmission.body:(latest?.submission|| (original?{requestId:latest.requestId,text:original.content}:null));if(submission&&!busy.value)submit(submission,lastSubmission?.key===selected.value?lastSubmission.kind:latest?.kind==='group_invitation'?'invitation':'message');
}
async function invite(){if(!invitedAgent.value||busy.value||currentTopic.value?.executable===false)return;await submit({requestId:crypto.randomUUID(),agentId:invitedAgent.value},'invitation');}
function needsReview(j){return ['review_required','blocked_config'].includes(j.state)||(j.state==='cancelled'&&!j.reviewResolved&&j.errorCode?.endsWith('REVIEW_REQUIRED'));}
async function abandon(j){if(!reviewChecks.value[j.id])return;try{await api('executions/'+j.id+'/resolve',{action:'acknowledge_and_abandon_remaining'});notice.value='本次剩余接力已放弃，可提交新消息；旧步骤不会重跑。';await refresh();}catch(e){notice.value=e.message;}}
async function cancel(id){try{await api('executions/'+id+'/cancel',{});await refresh();}catch(e){notice.value=e.message;}}
function clearTransientKey(){accessKey.value='';pairCode.value='';}
onMounted(async()=>{await connectionInfo();await session();timer=setInterval(refresh,2000);window.addEventListener('pagehide',clearTransientKey);});
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('pagehide',clearTransientKey);clearTransientKey();});
</script>
<template>
 <div class="shell">
  <header><img :src="'/mobile/icon.svg'" alt=""><div><strong>VCP Mobile</strong><small>同一段会话，随时接续</small></div><span class="connection" :class="{offline:!online}">{{online?(paired?'已连接':'服务可达'):'离线'}}</span><button id="open-settings" class="settings-toggle" @click="settingsOpen=!settingsOpen">设置</button></header>
  <main v-if="settingsOpen||!paired" class="pairing settings">
   <div class="intro">连接你的会话</div><p>输入 VCPToolBox API Key。服务器和连接参数已自动配置。</p>
   <form @submit.prevent="connect">
    <details :open="settingsOpen"><summary>连接设置</summary><label for="server-address">后端地址</label><input id="server-address" v-model="serverUrl" type="url" required @input="tested=false;accessKey=''" :disabled="busy">
    <button id="test-connection" type="button" @click="testConnection" :disabled="busy">测试连接</button>
    <p v-if="server" id="server-info">{{server.service}} · {{server.plugin}}<br>{{server.serverUrl||'尚未配置正式后端'}}</p></details>
    <p v-if="!keyAllowed" id="connection-blocker">安全接入尚未确认，访问凭据输入暂不可用。</p>
    <label for="server-key">访问凭据 · VCPToolBox API Key</label><input id="server-key" v-model="accessKey" type="password" autocomplete="off" autocapitalize="off" spellcheck="false" :disabled="busy||!keyAllowed||!tested" :placeholder="keyAllowed&&tested?'只需输入你的 Key':'HTTPS 安全入口就绪后可输入'" :required="keyAllowed&&tested">
    <button id="save-connection" :disabled="busy||!tested||!keyAllowed||!accessKey">{{paired?'重新认证并保存连接':'保存服务器连接'}}</button>
   </form>
   <div v-if="paired" class="device-actions"><button id="disconnect" @click="disconnect" :disabled="busy">断开连接</button><button id="clear-session" @click="disconnect" :disabled="busy">清除设备会话</button><button id="close-settings" @click="settingsOpen=false">返回会话</button></div>
   <details v-if="!paired"><summary>使用一次性配对码</summary><form @submit.prevent="pair"><label for="pair-code">一次性配对码</label><input id="pair-code" v-model="pairCode" type="password" autocomplete="off" required><button id="pair-submit" :disabled="busy">连接会话</button></form></details>
   <p role="status">{{notice}}</p>
  </main>
  <template v-else>
   <nav><div class="agent-heading"><img v-if="agents.find(a=>a.id===agentId)?.avatar" :src="agents.find(a=>a.id===agentId).avatar" alt="Agent 头像"><div><label for="agent-select">Agent / 群聊</label><select id="agent-select" v-model="agentId" @change="selectAgent" :disabled="busy"><option v-for="a in agents" :key="a.id" :value="a.id">{{a.name}}</option></select></div></div><label for="topic-select">历史话题</label><select id="topic-select" v-model="selected" @change="changeTopic" :disabled="busy"><option v-for="t in visibleTopics" :key="t.key" :value="t.key">{{t.topicName}} · {{t.messageCount}} 条</option></select><small v-if="currentTopic" class="topic-detail"><template v-if="currentTopic.configVersion">配置 v{{currentTopic.configVersion}} · </template>{{currentTopic.topicId}} · {{currentTopic.model||'未配置模型'}} · {{currentTopic.historyReady===false?'等待电脑首次同步':currentTopic.executable===false?(errors[currentTopic.unavailableReason]||'仅可阅读'):'可继续对话'}}<template v-if="currentTopic.updatedAt"> · {{new Date(currentTopic.updatedAt).toLocaleString()}}</template></small></nav>
   <section ref="history" id="history" aria-label="聊天历史"><div class="start">会话 · 服务端持久保存</div><article v-for="m in messages" :key="m.id" class="message" :class="m.role" :data-message-id="m.id"><small>{{m.role==='user'?'你':(m.name||currentTopic?.agentName||'Agent')}}</small><div class="bubble">{{typeof m.content==='string'?m.content:'此消息包含非文本内容，请在桌面查看'}}</div><div v-if="m.attachments?.length" class="attachments"><div v-for="a in m.attachments" :key="a.id" class="attachment"><template v-if="attachmentStates[m.id+'/'+a.id]?.state==='available'"><img v-if="attachmentStates[m.id+'/'+a.id]?.type?.startsWith('image/')" :src="attachmentUrl(m,a)" :alt="a.name||'图片附件'" loading="lazy"><a :href="attachmentUrl(m,a)" target="_blank" rel="noopener">{{a.name||'查看附件'}}</a><details v-if="a.extractedText"><summary>查看文本</summary><pre>{{a.extractedText}}</pre></details></template><span v-else>{{a.name||'附件'}} · {{attachmentStates[m.id+'/'+a.id]?.state==='corrupt'?'完整性校验失败':'附件暂未同步或正在确认'}}</span></div></div></article><p v-if="!messages.length" class="empty">{{currentTopic?.historyReady===false?'正在等待电脑同步所选历史，完成后即可接续。':'还没有消息，发送一条开始会话。'}}</p></section>
   <section class="executions" aria-label="执行状态"><article v-for="j in jobs" :key="j.id" class="execution-job" :data-exec-id="j.id" :data-state="j.state"><div class="execution-row"><span>{{errors[j.errorCode]?errors[j.errorCode]:(labels[j.state]||j.state)}}<template v-if="j.steps"> · {{j.steps.filter(s=>s.state==='completed').length}} / {{j.stepCount}} 位成员</template></span><button v-if="j.own&&['queued','running','waiting_approval'].includes(j.state)" :data-cancel-id="j.id" @click="cancel(j.id)">取消剩余接力</button></div><ol v-if="j.steps" class="group-steps"><li v-for="step in j.steps" :key="step.id">{{step.name}} · {{labels[step.state]||step.state}}<small v-if="step.errorCode"> · {{errors[step.errorCode]||'本步异常，详情请核对原生宿主'}}</small></li></ol><div v-if="j.own&&needsReview(j)" class="review-state"><p>请先在原生宿主核对工具是否已执行。这里不会批准工具，也不会重跑旧步骤。</p><label><input type="checkbox" v-model="reviewChecks[j.id]">我已核对，放弃本次剩余接力</label><button @click="abandon(j)" :disabled="!reviewChecks[j.id]">结束本次并解除暂停</button></div></article></section>
   <footer><div v-if="currentTopic?.ownerType==='group'" class="group-invitation"><label for="group-invite">邀请成员发言</label><select id="group-invite" v-model="invitedAgent" :disabled="busy||currentTopic.executable===false"><option value="">选择成员</option><option v-for="member in currentTopic.members||[]" :key="member.id" :value="member.id" :disabled="member.unavailable">{{member.name}}{{member.unavailable?' · 暂不可用':''}}</option></select><button @click="invite" :disabled="busy||!invitedAgent||currentTopic.executable===false">邀请</button></div><div v-if="currentTopic?.attachmentsEnabled" class="upload-area"><label class="attachment-picker">添加图片或文件<input type="file" accept=".png,.jpg,.jpeg,.webp,.pdf,.txt,.md,.csv,.json" multiple @change="selectFiles" :disabled="busy||currentTopic?.executable===false"></label><small>最多 8 个，每个 20 MB；断线后可重新选择同一文件续传。</small><div v-for="(item,i) in pendingFiles" :key="i" class="pending-file"><span>{{item.file.name}} · {{item.error||item.progress+'%'}}</span><button @click="pendingFiles.splice(i,1)" :disabled="busy">移除</button></div></div><form @submit.prevent="send"><label class="sr-only" for="message-text">消息</label><textarea id="message-text" v-model="text" placeholder="输入文字…" rows="2" maxlength="12000" :disabled="currentTopic?.executable===false"></textarea><button id="send" :disabled="busy||(!text.trim()&&!pendingFiles.length)||currentTopic?.executable===false">发送</button></form><div class="send-state"><span id="send-state" role="status">{{notice}}</span><button id="retry-last" @click="retry" :disabled="busy">核对 / 重试提交</button></div></footer>
  </template>
 </div>
</template>
